import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"NetPilot — Go Network Toolkit","description":"A single-binary network toolkit in pure Go: port scanner, TCP ping, HTTP health checks, DNS lookups. Zero dependencies, cross-platform.","frontmatter":{"title":"NetPilot — Go Network Toolkit","description":"A single-binary network toolkit in pure Go: port scanner, TCP ping, HTTP health checks, DNS lookups. Zero dependencies, cross-platform."},"headers":[],"relativePath":"en/projects/netpilot/index.md","filePath":"en/projects/netpilot/index.md"}`),a={name:`en/projects/netpilot/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="netpilot-—-go-network-toolkit" tabindex="-1">NetPilot — Go Network Toolkit <a class="header-anchor" href="#netpilot-—-go-network-toolkit" aria-label="Permalink to “NetPilot — Go Network Toolkit”">​</a></h1><p><strong><a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">NetPilot</a></strong> is my answer to a simple annoyance: checking network reachability should not require installing five different tools or memorizing <code>nmap</code> flags. NetPilot compiles to <strong>one static binary in pure Go</strong> — no runtime, no dependencies, no scripts — and answers the questions I ask networks every day.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Job</th></tr></thead><tbody><tr><td><code>scan</code></td><td>Fast TCP port scanning with worker pools and timeouts.</td></tr><tr><td><code>tping</code></td><td>TCP-level ping that works where ICMP is blocked.</td></tr><tr><td><code>http</code></td><td>HTTP health checks with status, latency and TLS info.</td></tr><tr><td><code>dns</code></td><td>A/AAAA/MX/TXT lookups against any resolver.</td></tr><tr><td><code>info</code></td><td>Interface and routing summary for quick triage.</td></tr></tbody></table><h2 id="why-pure-go" tabindex="-1">Why pure Go <a class="header-anchor" href="#why-pure-go" aria-label="Permalink to “Why pure Go”">​</a></h2><p>Because deployment is the whole point. A network tool that needs Python, Node or a dozen system libraries fails exactly where you need it most — a minimal VPS, a container in a broken cluster, a friend&#39;s Windows laptop at 2 AM. <code>go build</code> produces one binary per platform; <code>CGO_ENABLED=0</code> keeps it portable. The concurrency model (goroutines + channels) makes the scanner fast without thread headaches.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># scan the well-known range of a host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./netpilot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ports</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1-1024</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># tcp-ping a flaky service./netpilot tping db.internal:5432 --count 10</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># health-check with JSON output for scripts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./netpilot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/health</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="what-i-learned-building-it" tabindex="-1">What I learned building it <a class="header-anchor" href="#what-i-learned-building-it" aria-label="Permalink to “What I learned building it”">​</a></h2><p>The interesting engineering was not the scanning — it was the edge cases: rate-limiting yourself so you do not DoS your own gateway, handling half-open connections, honoring timeouts that actually mean something, and making JSON output stable enough to script against. It also became my reference project for learning how far agent teams can take a well-specified CLI.</p><div class="tip custom-block"><p class="custom-block-title">Try it</p><p>Clone, <code>go build</code>, done: <a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">github.com/Godde3s/netpilot</a> — MIT licensed.</p></div>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};